import{_ as e,o as r,c as o,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"2019-08-19 :: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2019-08-19 :: Ceph Orchestration Meeting","date":"2019-08-19T00:00:00.000Z","updated":"2019-08-20T00:00:00.000Z","tags":["Ceph","Distributed Storage","Orchestration","OSD Replacement","CephFS","Rook"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-08-19_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2019/2019-08-19_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780459816000}'),i={name:"posts/2019/2019-08-19_-_-_Ceph_Orchestration_Meeting.md"};function n(a,t,p,_,l,c){return r(),o("div",null,[...t[0]||(t[0]=[s("<p>本次会议主要围绕Ceph分布式存储项目的讨论展开，包括OSD替换、功能冻结、Rook与Orchestrator的兼容性等关键议题。</p><p><strong>关键细节与讨论议题</strong>：</p><ol><li><p><strong>OSD替换</strong>：Petrus指出，当前替换OSD的流程存在困难，因为orchestrator API缺少必要的代码支持。讨论了通过orchestrator API调用set_volume创建新OSD并指定现有OSD ID的需求，以及通过UI界面简化OSD替换流程的可能性。</p></li><li><p><strong>功能冻结</strong>：Petrus提到，Ceph 1.1版本的特性冻结将在本周五进行，预计9月初发布。讨论了可能影响Orchestrator的功能，如disruption budgets、bucket object bucket claims等。</p></li><li><p><strong>Rook与Orchestrator兼容性</strong>：Petrus表示，Orchestrator团队将专注于确保最新master分支的Rook与最新Rook版本兼容，并讨论了兼容性问题及未来版本的规划。</p></li><li><p><strong>其他议题</strong>：讨论了Ceph集群的启动过程，以及是否需要使用safethought conf等配置文件。还讨论了将override config代码从CRD中移除的PR。</p></li></ol><p><strong>决定事项</strong>：</p><ol><li>Petrus将与Chief讨论如何改进Orchestrator的UI，以简化OSD替换流程。</li><li>Petrus将关注Ceph 1.1版本的发布，确保Orchestrator的兼容性。</li><li>Joey将关注将override config代码从CRD中移除的PR。</li></ol><p><strong>后续行动计划</strong>：</p><ol><li>Petrus将与Chief讨论并改进Orchestrator的UI。</li><li>Petrus将关注Ceph 1.1版本的发布，并与Rook团队沟通兼容性问题。</li><li>Joey将关注PR的进展，并确保override config代码从CRD中移除。</li></ol>",7)])])}const d=e(i,[["render",n]]);export{g as __pageData,d as default};
